cials","image":"/inspiration/brands/asteor/04-social-profile.webp","thumbnail":"/inspiration/brands/asteor/04-social-profile-small.webp","width":1600,"height":783,"contentHash":"38d02aef98ad5dbdd89ad5b571e2eb17b05ae7bd62d396b4c1399a390f760849","fill":"#1c1c1c","description":"Two profile cards labeled Art Studio: a chartreuse as monogram on a black avatar and on a blue avatar, under blurred blue abstract banners."},{"part":"visuals","image":"/inspiration/brands/asteor/05-brand-poster.webp","thumbnail":"/inspiration/brands/asteor/05-brand-poster-small.webp","width":1600,"height":1261,"contentHash":"c602fb23b0ddd7050a5b74d85f02b709ff4e1f134fe91fbd1a465b42c56983cb","description":"Two framed posters on a dark slatted wall, each a vivid surreal portrait illustration in purple, pink, orange and teal with the asteor logo below."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
