ds/auraic/04-social-profile-small.webp","width":1600,"height":846,"contentHash":"e9bf002e0dd773022e349b49bac5aa7c6606a6b4005d2512fdce794a5fc76701","description":"Facebook-style page on a black rocky backdrop: a red-pink banner with LUXURY and skincare bottles, and a round avatar with a stylized A."},{"part":"visuals","image":"/inspiration/brands/auraic/05-brand-poster.webp","thumbnail":"/inspiration/brands/auraic/05-brand-poster-small.webp","width":1600,"height":900,"contentHash":"1a2ae209162c5fda0057b4a278377fffab3e2ef6dd8e34ec161f2c8a03c01070","description":"Bus-shelter ad on a city street: a beige-to-pink gradient poster with the AURAIC logo, large outlined LUXURY text and a script tagline."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
insert into fluid_private.inspiration_catalog(id,catalog_version,descriptor,relevant_elements) values('a0602cd7-8d2e-575c-9d5c-6b7fadcee36e','2026-10-13.1','{"id":"a0602cd7-8d2e-575c-9d5c-6b7fadcee36e","slug":"aurox","brand":"Aurox","kind":"identity","description":"Energetic e-commerce identity with bright orange as the lead color, backed by electric blue and deep navy, a geometric sans and 3D shopping imagery.","image":"/inspiration/brands/aurox/01-logo.webp","width":1600,"height":770,"contentHash":"35f0b0a996c8247d53863abb1427986d77f1673586a661345c5804f4a8829869","elements":["logo","typography","colors","images","composition"],"tags":["ecommerce","orange","geometric","energetic"],"availableSince":"2026-11-08.1","parts":[{"part":"logo","image":"/inspiration/brands/aurox/01-logo.webp","thumbnail":"/inspiration/brands/aurox/01-logo-small.webp","width":1600,"height":770,"contentHash":"35f0b0a996c8247d53863abb1427986d77f1673586a661345c5804f4a8829869","fill":"#f6f5f4","description":"White geometric sans wordmark Aurox with a TM, the A drawn as an open chevron with no crossbar, on navy; the A alone is the brand mark."},{"part":"colors","image":"/inspiration/brands/aurox/02-color-palette.webp","thumbnail":"/inspiration/brands/aurox/02-color-palette-small.webp","width":1600,"height":1058,"contentHash":"b4b49e983d22c778fbb82c8fd558fde69c398febe4ff44c08af63b8541c3e0e5","fill":"#f5f5f4","description":"Cart Alert Orange #FF6D00 (primary), Hyperlink Blue #145DFF, Midnight Void navy #11142F, Direct-Red #E6222B and Eco-Growth Green #96C828."},{"part":"typefaces","image":"/inspiration/brands/aurox/03-typography.webp","thumbnail":"/inspiration/brands/aurox/03-typography-small.webp","width":1600,"height":1054,"contentHash":"b04f8fc95204c56a9438b1b0617228a74261596c5bfbfa2ee915be85c058123f","fill":"#f5f4f3","description":"Satoshi, a geometric sans, shown in Light, Regular, Medium, Bold and Black."},{"part":"socials","image":"/inspiration/brands/aurox/04-social-profile.webp","thumbnail