x/04-social-profile.webp","thumbnail":"/inspiration/brands/curvex/04-social-profile-small.webp","width":1600,"height":900,"contentHash":"c6a08dc819f8bfad4b8afee25a537145ad11df0aba607cde0921d5e243ce9cff","fill":"#eeeadf","description":"Dark profile card on cream: a header photo of oil being poured into an engine, a gold-ringed chevron avatar and a bio about vehicle service and repair."},{"part":"visuals","image":"/inspiration/brands/curvex/05-brand-poster.webp","thumbnail":"/inspiration/brands/curvex/05-brand-poster-small.webp","width":1600,"height":1120,"contentHash":"79dc4a6b8f7daf721042d234adf949df5caa8e9d72a3bcbd5f4d3a551b94b42a","description":"Two backlit posters in a dark garage: Precision Service for Modern Vehicles with a large gold chevron, and The future of vehicle care starts here."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
