,"thumbnail":"/inspiration/brands/eduflow/04-social-profile-small.webp","width":1600,"height":844,"contentHash":"bf9b9b084d426fdc70f60e2845a1ac67aaf3f776238c48351a6ff98a6eb33ed3","description":"Two profile cards labeled Ed-Tech on a green background: blue and orange avatars with the white E symbol, under blue abstract banners."},{"part":"visuals","image":"/inspiration/brands/eduflow/05-brand-poster.webp","thumbnail":"/inspiration/brands/eduflow/05-brand-poster-small.webp","width":1600,"height":1231,"contentHash":"16affc7afd33cf3dfb0c24a37bfa6206683268b2efd7e94a98ab54cf3c506900","description":"Wall billboard with a passerby: Closing the Skill Gap, Education Built For Innovation! on blue, with a smiling student holding notebooks and orange swooshes."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
insert into fluid_private.inspiration_catalog(id,catalog_version,descriptor,relevant_elements) values('cb312465-0db9-58bd-a4df-e75c59c475c9','2026-10-13.1','{"id":"cb312465-0db9-58bd-a4df-e75c59c475c9","slug":"fleetex","brand":"Fleetex","kind":"identity","description":"Clean enterprise software identity for fleet management in periwinkle blue-violet, cool gray and near-black, with a geometric display sans and truck photography.","image":"/inspiration/brands/fleetex/01-logo.webp","width":1600,"height":900,"contentHash":"8cc1257918ae2137941196fc4f7ebe22fedcb992b1d96ea5b2124e9d315e2dbf","elements":["logo","typography","colors","images","composition"],"tags":["saas","fleet-management","violet","geometric"],"availableSince":"2026-11-08.1","parts":[{"part":"logo","image":"/inspiration/brands/fleetex/01-logo.webp","thumbnail":"/inspiration/brands/fleetex/01-logo-small.webp","width":1600,"height":900,"contentHash":"8cc1257918ae2137941196fc4f7ebe22fedcb992b1d96ea5b2124e9d315e2dbf","description":"Blue-violet F symbol with two bars and a curved, shield-like stem, beside the white geometric sans wordmark Fleetex; variants on navy, violet, white and gray."},{"part":"colors","image":"/inspiration/brands/fleetex/02-color-palette.webp","thumbnail":"/inspiration/brands/fleetex/02-color-palette-small.webp","width":1600,"height":900,"contentHash":"c412d33cc09785c3b2546d1fe0771d2ce44b6f07c5f8095b38f59131ea359284","description":"Enterprise Blue #5B5CEB, Cool Gray #98A2B3, Carbon Black #121212 and Soft White #F8FAFC, beside a photo of branded trucks at a warehouse."},{"part":"typefaces","image":"/inspiration/brands/fleetex/03-typography.webp","thumbnail":"/inspiration/brands/fleetex/03-typography-small.webp","width":1600,"height":900,"contentHash":"d4ea0dd1468758d99cf41860eaa8397e2e08ff2f53cd792cb6f704958d88ab26","fill":"#111828","description":"Clash Display Variable, a geometric display sans, shown in Light, Regular, Medium, Semibold and Bold."},{"part":"socials","image":"/inspiration/brands/fleetex/04-social-profile.webp","thumbnail":"/inspiration/brands/fleetex/04-social-profile-small.webp","width":960,"height":1080,"contentHash":"8abb0852ba42aadbef304b9764562ec1aa5a16f20c54538607ec00fd28c805d7","fill":"#5b5ce8","description":"Profile card on blue-violet: a photo of branded trucks and a van, a violet F avatar and a bio about software for connected fleets."},{"part":"visuals","image":"/inspiration/brands/fleetex/05-brand-poster.webp","thumbnail":"/inspiration/brands/fleetex/05-brand-poster-small.webp","width":1600,"height":933,"contentHash":"3f8f9b096394fc16664491b8a36cd54d2f66b80c9ab9c765fa09498e79c226a3","description":"Wall display in a dark corridor: Manage Every Vehicle. Optimize Every Mile. beside a desktop dashboard with a map and a phone app, plus three feature labels."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
