profile-small.webp","width":1600,"height":1200,"contentHash":"69630bf99711271208f8fd448555e4862c4ea4501dd4a6e6b6247225624d5285","description":"Dark X profile reading Reimagine remittance with Flyra and a green avatar, beside a glassy tile with a chrome-and-green 3D version of the symbol."},{"part":"visuals","image":"/inspiration/brands/flyra/05-brand-poster.webp","thumbnail":"/inspiration/brands/flyra/05-brand-poster-small.webp","width":1600,"height":1092,"contentHash":"c125a9a7a499312afe89b882d9f2a6d39b15fdce06f41e0d340b4f703c0ed3a3","fill":"#0f0f0f","description":"Dark wall screen with a quote, Sending money shouldn''t cost more than your morning coffee., signed with the Flyra logo, as a person walks past in silhouette."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
