":"/inspiration/brands/glowe/04-social-profile-small.webp","width":1600,"height":1040,"contentHash":"00c203b7ccd15fd16871e55ac2a869a80cc89862cc32f9785d8df97b91648db8","fill":"#fbf6f3","description":"Facebook page mockup on cream: the drop logo and tagline, three arched photos of faces and magenta petals, and a plum circular avatar."},{"part":"visuals","image":"/inspiration/brands/glowe/05-brand-poster.webp","thumbnail":"/inspiration/brands/glowe/05-brand-poster-small.webp","width":1600,"height":900,"contentHash":"986cc205568c810f82b3efdffce504b1d93ef01efb94756760fc5e6735f5ec91","description":"Three framed posters on a softly shadowed wall: a woman in a towel touching her face, a plum poster reading BEAUTY, SKIN & LIFE, and a face with white flowers."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
