piration/brands/paymok/04-social-profile.webp","thumbnail":"/inspiration/brands/paymok/04-social-profile-small.webp","width":1600,"height":1979,"contentHash":"29b08afaa625597f7d05ce7899ae6b8edfc9419cc14c01c7f2daaf318ec77d74","description":"On violet: a profile with a blue 3D petal banner, a notification, a phone app icon and three posts such as Finance Without Boundaries on dark gradients."},{"part":"visuals","image":"/inspiration/brands/paymok/05-brand-poster.webp","thumbnail":"/inspiration/brands/paymok/05-brand-poster-small.webp","width":1600,"height":1085,"contentHash":"74fe7cda5679c2e190d38e8b2a6bd3467423e1abbc818dde8cf2c2e8b1877330","description":"Billboard in a dark modern space above tall grass: The Future of Digital Payments. on violet beside 3D dollar and bitcoin coins and payment cards."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
