ebp","width":630,"height":710,"contentHash":"8fe3b00e9f365ab8add1490c327f53a92c969bfd0dcf49fc41fdf486244e948f","fill":"#9b002a","description":"Profile card on crimson with a crimson R avatar and a bio describing security inspired by the eagle''s vision."},{"part":"visuals","image":"/inspiration/brands/raygle/05-brand-poster.webp","thumbnail":"/inspiration/brands/raygle/05-brand-poster-small.webp","width":1400,"height":788,"contentHash":"196b9cda24463118820203d99a528ae4fead6f6b7436e3cfab1169e8f2a699b7","description":"Billboard on a gray tiled wall: Intelligent Security for a World That Never Stops Changing. on crimson, beside a man in sunglasses using a walkie-talkie."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
