travil/04-social-profile-small.webp","width":934,"height":953,"contentHash":"649b6a36ee450777dec633915d39ea38ee5cdd22e4eccec939abb583a3f17bfa","fill":"#1d1d1d","description":"Profile card with a green banner holding a large dark arrow shape, a dark avatar with the green arrow and a bio about a modern travel brand."},{"part":"visuals","image":"/inspiration/brands/travil/05-brand-poster.webp","thumbnail":"/inspiration/brands/travil/05-brand-poster-small.webp","width":1600,"height":1200,"contentHash":"f44b54ed659253299d3d098e8c90ec3e353587ae2d17d39062a0e0c8d45cffd7","description":"Construction hoarding under a crane: Travel More, Worry Less with green highlights, and a smiling woman in a sun hat hugging a yellow suitcase."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
