brands/zapp/04-social-profile-small.webp","width":938,"height":1038,"contentHash":"37e17a691d3fbfae24166ee3cf25afbc9f20117d023a4e6b0f259d9585ea5fda","fill":"#fffdf5","description":"Profile card with lime and gray diagonal shapes and a cartoon robot with a visor and lightning bolts, above a dark panel with a navy zapp avatar."},{"part":"visuals","image":"/inspiration/brands/zapp/05-brand-poster.webp","thumbnail":"/inspiration/brands/zapp/05-brand-poster-small.webp","width":1500,"height":892,"contentHash":"a64fe66506505a7f986bab7aefa444a3ee76b39d997436ad7323f53a2263d221","description":"Billboard on a dark tiled wall: lime Download the Z-app with map pins and a smiling man holding a phone, plus the zapp logo."}]}'::jsonb,array['logo','typography','colors','images','composition']::text[]);
